      {contextNotice&&<SystemMessage><section className="px-inline-card px-context-card" role="status"><span className="px-eyebrow">上下文已隔离</span><h2>请在当前可信会话重新开始</h2><p>{contextNotice}</p></section></SystemMessage>}
      {!turn&&!visibleAssistance&&!selectedId&&<SystemMessage><section className="px-welcome"><h2>你希望解决什么问题？</h2><p>直接描述即可。平台会先完成精确授权，再通过 AI 补问或生成可修改草稿；只有你确认后才会创建正式 Problem。</p><p>首批合成 transport 与真实 provider 会明确区分；页面不会自动调用数字员工、Agent、Skill、知识库或附件。</p></section></SystemMessage>}
      {visibleAssistance&&!turn&&<UserMessage>{visibleAssistance.originalText}</UserMessage>}
      {visibleAssistance&&<SystemMessage label="AI 辅助"><DraftAssistanceCard result={visibleAssistance.result} busy={busy} onRefresh={()=>void refreshAssistance()} onObserve={()=>void observeAssistance()} onCancel={()=>void cancelAssistance()} onReject={()=>void rejectAssistance()} onManualFallback={manualFallback}/>{failure&&["请求 AI 草稿辅助","刷新 AI 草稿辅助","观察 AI 原调用","取消 AI 草稿辅助","拒绝 AI 草稿","补记草稿来源"].includes(failure.operation)&&<WorkbenchErrorNotice {...failure} onRetry={failure.operation==="补记草稿来源"?()=>void repairProblemLink():visibleAssistance.result.state==="OUTCOME_UNKNOWN"?()=>void observeAssistance():()=>void refreshAssistance()} retryLabel={failure.operation==="补记草稿来源"?"仅重试来源补记":"继续原辅助调用"}/>}</SystemMessage>}
