function CreatedProblemCard({revision,restored}:{revision:BusinessProblemRevision;restored:boolean}){return <section id="created-problem-message" tabIndex={-1} className="px-inline-card px-created-card is-complete"><header><div><span className="px-eyebrow">创建结果</span><h2>{restored?"已恢复正式业务记录":"业务问题已创建"}</h2></div><span className="px-status success">已创建</span></header><details><summary>查看创建事实</summary><p>{restored?"此卡片来自当前正式 Problem 端口允许读取的业务事实，不是恢复的聊天历史。":"创建响应已经确认；后续聊天不会覆盖这条已提交事实。"}</p><dl><dt>Problem ID</dt><dd><code>{revision.business_problem_id}</code></dd><dt>Problem Revision</dt><dd><code>{revision.revision_id}</code></dd><dt>Digest</dt><dd><code>{revision.digest}</code></dd></dl></details></section>}

function FormalProblemCard({detail,draft,editing,composerEditing,busy,dirty,titleError,descriptionError,onChange,onEdit,onEditWithComposer,onCancel,onSave}:{detail:BusinessProblemDetail;draft:RecordDraft;editing:boolean;composerEditing:boolean;busy:boolean;dirty:boolean;titleError:string;descriptionError:string;onChange:(value:RecordDraft)=>void;onEdit:()=>void;onEditWithComposer:()=>void;onCancel:()=>void;onSave:()=>void}){
  const current=detail.revisions.find(item=>item.revision_id===detail.problem.current_revision_id)??latest(detail.revisions);
  return <section id="formal-problem-message" tabIndex={-1} className="px-inline-card px-formal-card"><header><div><span className="px-eyebrow">问题详情</span><h2>读取成功</h2></div><span className="px-status success">已读取</span></header><p className="px-truth-note">已获得查看权限并读取问题详情；修改此问题需要另行授权。</p>{editing?<><label className="px-field" htmlFor="problem-title"><span>问题名称（可选修改）</span><input id="problem-title" maxLength={200} value={draft.title} aria-invalid={Boolean(titleError)} disabled={busy} onChange={event=>onChange({...draft,title:event.target.value})}/>{titleError&&<strong className="px-field-error">{titleError}</strong>}</label><label className="px-field" htmlFor="problem-description"><span>完整描述</span><textarea id="problem-description" maxLength={2_000} value={draft.description} aria-invalid={Boolean(descriptionError)} disabled={busy} onChange={event=>onChange({...draft,description:event.target.value})}/>{descriptionError&&<strong className="px-field-error">{descriptionError}</strong>}</label><div className="px-card-actions"><button type="button" disabled={busy} onClick={onCancel}>放弃修改</button><button type="button" disabled={busy} onClick={onEditWithComposer}>使用输入框完整修改</button><button type="button" className="px-primary-button" disabled={busy||!dirty} onClick={onSave}>{busy?"正在保存…":"保存正式修订"}</button></div></>:composerEditing?<><h3>{draft.title}</h3><p>{draft.description}</p><p className="px-mode-note">正在底部输入框完整替换描述；卡片字段和保存操作暂时停用。</p></>:<><h3>{current?.title}</h3><p>{current?.description}</p><button type="button" disabled={busy} onClick={onEdit}>修改正式问题</button></>}<details><summary>技术详情</summary><p>查看权限批准后，本页执行 fresh exact GET；READ 不隐含 REVISE。</p><dl><dt>Problem ID</dt><dd><code>{detail.problem.business_problem_id}</code></dd><dt>Problem Revision</dt><dd><code>{current?.revision_id}</code></dd><dt>Aggregate Version</dt><dd>{detail.problem.aggregate_version}</dd><dt>Owner</dt><dd>{current?.owner_id}</dd></dl></details></section>;
}

function AuthorizationCard({state,busy,readComplete,onRequest,onRefresh}:{state:AuthorizationState;busy:boolean;readComplete:boolean;onRequest:()=>void;onRefresh:()=>void}){
  const continuation=state.continuation,request=state.request;
  return <section id="authorization-message" tabIndex={-1} className="px-inline-card px-authorization-card"><header><div><span className="px-eyebrow">授权状态</span><h2>申请查看权限</h2></div></header>{continuation?.state==="AVAILABLE"&&!request&&<><p>问题已创建，但查看问题详情需要独立授权。提交后请把准确申请编号交给管理员。</p><button className="px-primary-button" disabled={busy} onClick={onRequest}>{busy?"正在提交…":state.requestKey?"恢复原授权申请":"申请查看权限"}</button></>}{continuation?.state==="CONSUMED"&&!request&&<p>查看申请已经提交。页面只恢复原申请，不会重复提交。</p>}{continuation?.state==="EXPIRED"&&<><span className="px-status danger">申请窗口已过期</span><p>已创建问题仍保留；页面不会自动延长窗口、撤销创建或换新标识重建。</p></>}{request&&<><div className="px-request-status"><span className={`px-status ${request.state==="APPROVED"?"success":request.state==="REJECTED"?"danger":"warning"}`}>{request.state==="APPROVED"?"已批准":request.state==="REJECTED"?"已拒绝":"等待管理员处理"}</span><p>{request.state==="PENDING"?"将申请编号交给独立管理员；处理后在这里刷新。":request.state==="REJECTED"?"管理员已拒绝；页面不会读取问题详情。":readComplete?"授权已批准；问题详情已读取成功。":"授权已批准；页面会重新读取，成功后才显示问题详情。"}</p></div><dl><dt>申请编号</dt><dd><code>{request.requestId}</code></dd><dt>状态版本</dt><dd>{request.aggregateVersion}</dd></dl><button id="refresh-authorization" disabled={busy} onClick={onRefresh}>{busy?"正在刷新…":"刷新授权状态"}</button></>}{(continuation||request)&&<details><summary>授权技术详情</summary>{request&&<p>批准后通过 fresh exact GET 读取；READ 权限不包含 REVISE。</p>}{continuation&&<dl><dt>Continuation 状态</dt><dd>{continuation.state}</dd><dt>申请窗口到期</dt><dd>{readable(continuation.expiresAt)}</dd></dl>}</details>}</section>;
}

function CriteriaWorkspaceAuthorization({authorization,busy,onRequest,onRefresh}:{authorization:CriteriaAuthorizationState|null;busy:boolean;onRequest:()=>void;onRefresh:()=>void}){
  const request=authorization?.request;
  return <section className="px-inline-card px-boundary-card"><span className="px-eyebrow">成功标准权限</span><h2>尚未读取成功标准</h2><p>业务问题 READ 不包含成功标准或集合的读取、创建、修订权限。页面不会把不可读状态显示成“未配置”。</p>{!authorization&&<button type="button" className="px-primary-button" disabled={busy} onClick={onRequest}>申请定义与读取权限</button>}{authorization&&!request&&<p className="px-mode-note">正在提交正式申请；申请本身不会授予权限。</p>}{request&&<><span className={`px-status ${request.state==="APPROVED"?"success":request.state==="REJECTED"?"danger":"warning"}`}>{request.state==="PENDING"?"等待独立审批":request.state==="APPROVED"?"已批准":"已拒绝"}</span><dl><dt>申请编号</dt><dd><code>{request.requestId}</code></dd><dt>请求操作</dt><dd>{request.requestedActions.join(", ")}</dd></dl><div className="px-card-actions">{request.state==="PENDING"&&<a href={`/authorization-admin?request=${encodeURIComponent(request.requestId)}`} target="_blank" rel="noreferrer">在独立管理员窗口打开</a>}<button type="button" disabled={busy} onClick={request.state==="REJECTED"?onRequest:onRefresh}>{request.state==="REJECTED"?"重新提交新申请":busy?"正在检查…":"刷新权限状态并继续"}</button></div></>}</section>;
}
